  1170→/* ── Navbar scroll + pill ── */
  1171→const navbar = document.getElementById('navbar');
  1172→window.addEventListener('scroll', () => {
  1173→    navbar.classList.toggle('scrolled', window.scrollY > 60);
  1174→}, { passive: true });
  1175→
  1176→/* ── Active nav link tracking ── */
  1177→const sections = document.querySelectorAll('section[id]');
  1178→const navLinks = document.querySelectorAll('.nav-link-item');
  1179→const navObs = new IntersectionObserver((entries) => {
  1180→    entries.forEach(e => {
  1181→        if (e.isIntersecting) {
  1182→            navLinks.forEach(l => l.classList.remove('nav-active'));
  1183→            const active = document.querySelector(`.nav-link-item[href="#${e.target.id}"]`);
  1184→            if (active) active.classList.add('nav-active');
  1185→        }
  1186→    });
  1187→}, { threshold: 0.35, rootMargin: '-60px 0px -40% 0px' });
  1188→sections.forEach(s => navObs.observe(s));
  1189→
  1190→/* ── Mobile menu ── */
  1191→const toggle    = document.getElementById('navToggle');
  1192→const mobileMenu = document.getElementById('mobileMenu');
  1193→const mobileClose = document.getElementById('mobileClose');
  1194→toggle.addEventListener('click', () => {
  1195→    const open = mobileMenu.classList.toggle('open');
  1196→    toggle.classList.toggle('open', open);
  1197→    document.body.style.overflow = open ? 'hidden' : '';
  1198→});
  1199→mobileClose.addEventListener('click', closeMobile);
  1200→function closeMobile() {
  1201→    mobileMenu.classList.remove('open');
  1202→    toggle.classList.remove('open');
  1203→    document.body.style.overflow = '';
  1204→}
  1205→
  1206→/* ── Hero slideshow ── */
  1207→(function initSlider() {
  1208→    const slides = document.querySelectorAll('.hero-slide');
  1209→    const dots   = document.querySelectorAll('.hero-dot');
  1210→    let current  = 0;
  1211→    let timer    = null;
  1212→    function goTo(idx) {
  1213→        slides[current].classList.remove('active');
  1214→        dots[current].classList.remove('active');
  1215→        current = (idx + slides.length) % slides.length;
  1216→        slides[current].classList.add('active');
  1217→        dots[current].classList.add('active');
  1218→    }
  1219→    function startAuto() { timer = setInterval(() => goTo(current + 1), 6000); }
  1220→    dots.forEach(dot => {
  1221→        dot.addEventListener('click', () => {
  1222→            clearInterval(timer);
  1223→            goTo(parseInt(dot.dataset.slide));
  1224→            startAuto();
  1225→        });
  1226→    });
  1227→    startAuto();
  1228→})();
  1229→
  1230→/* ── Particles ── */
  1231→(function createParticles() {
  1232→    const container = document.querySelector('.hero');
  1233→    if (!container) return;
  1234→    const wrap = document.createElement('div');
  1235→    wrap.style.cssText = 'position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:1;';
  1236→    for (let i = 0; i < 18; i++) {
  1237→        const p = document.createElement('div');
  1238→        p.className = 'particle';
  1239→        const size = Math.random() * 3 + 2;
  1240→        p.style.cssText = `width:${size}px;height:${size}px;left:${Math.random()*100}%;animation-duration:${Math.random()*15+10}s;animation-delay:${Math.random()*10}s;opacity:${Math.random()*.4+.15};`;
  1241→        wrap.appendChild(p);
  1242→    }
  1243→    container.appendChild(wrap);
  1244→})();
  1245→
  1246→/* ── Scroll-reveal ── */
  1247→const revealEls = document.querySelectorAll('.reveal');
  1248→const revealObs = new IntersectionObserver((entries) => {
  1249→    entries.forEach(e => {
  1250→        if (e.isIntersecting) { e.target.classList.add('visible'); revealObs.unobserve(e.target); }
  1251→    });
  1252→}, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
  1253→revealEls.forEach(el => revealObs.observe(el));
  1254→
  1255→/* ── Count-up ── */
  1256→function countUp(el) {
  1257→    const target = parseInt(el.dataset.target, 10);
  1258→    if (!target) return;
  1259→    const exact  = el.dataset.exact === '1';
  1260→    const suffix = (!exact && target > 0) ? '+' : '';
  1261→    const duration = 1600;
  1262→    const step = target / (duration / 16);
  1263→    let current = 0;
  1264→    const timer = setInterval(() => {
  1265→        current = Math.min(current + step, target);
  1266→        el.textContent = Math.floor(current) + suffix;
  1267→        if (current >= target) clearInterval(timer);
  1268→    }, 16);
  1269→}
  1270→const countObs = new IntersectionObserver((entries) => {
  1271→    entries.forEach(e => {
  1272→        if (e.isIntersecting) { countUp(e.target); countObs.unobserve(e.target); }
  1273→    });
  1274→}, { threshold: 0.5 });
  1275→document.querySelectorAll('.count-up[data-target]').forEach(el => countObs.observe(el));
  1276→
  1277→/* ── Smooth anchor scroll ── */
  1278→document.querySelectorAll('a[href^="#"]').forEach(a => {
  1279→    a.addEventListener('click', e => {
  1280→        const id = a.getAttribute('href').slice(1);
  1281→        const target = document.getElementById(id);
  1282→        if (target) { e.preventDefault(); target.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
  1283→    });
  1284→});
  1285→</script>
